183→    FString UpdateUsdaAttribute(const FString& Content, const FString& PrimName, const FString& AttrName, const FString& NewValue, bool bIsString);
184→    void UpdateBehavioralSignals(FString& Content, float ResponseTimeMs);
185→
186→    // === USD PROFILE HANDLING ===
187→
188→    void OnUsdFileChanged();
189→    void ReloadUsdStage();
190→
191→    // === UTILITY ===
192→
193→    void WriteJsonToFile(const FString& Filename, const TSharedPtr<FJsonObject>& JsonObj);
194→    FString GetBridgeFilePath(const FString& Filename) const;
195→    void BridgeLog(const FString& Message) const;
196→
197→    // === STATE ===
198→
199→#if WITH_DIRECTORY_WATCHER
200→    FDelegateHandle WatchHandle;
201→#endif
202→
203→    bool bIsConnected = false;
204→    bool bUsePolling = false;
205→    bool bUsingUsdMode = false;  // v2.0.0: USD-native mode active
206→
207→    // Debouncing
208→    float TimeSinceLastStateChange = 0.0f;
209→    bool bStateChangePending = false;
210→    float TimeSinceLastUsdChange = 0.0f;
211→    bool bUsdChangePending = false;
