220→    FTranslatorsQuestion CurrentQuestion;
221→
222→    // === BEHAVIORAL SIGNALS (v2.0.0 ADHD_MoE routing) ===
223→
224→    TArray<float> ResponseTimes;  // Track response times for pattern detection
225→    int32 HesitationCount = 0;    // Count of long hesitations (>10s)
226→    int32 RapidClickCount = 0;    // Count of rapid clicks (<500ms)
